    def export_gt_supervision_for_current_image(self):
        """
        One-click GT export:
        - Loads main annotation x.json (no snapshots)
        - Takes ONLY manual atomics
        - Groups atomics using pure GT logic (gt_groups_from_midlines_and_gtmask)
        - Calls export_gt_supervision_for_image(...) with GT mask
        """

        import os, json
        import numpy as np
        import cv2

        from helpers.supervision import (
            export_gt_supervision_for_image as _export_gt_sup,
        )
        from combiner import gt_groups_from_midlines_and_gtmask

        base_name = self._image_base()

        if getattr(self, "original_image", None) is None:
            print("[GT_SUP] no image loaded.")
            return

        if getattr(self, "current_mask", None) is None:
            print("[GT_SUP] no GT mask loaded.")
            return

        H, W = self.original_image.shape[:2]
        gt_mask = (self.current_mask > 0).astype(np.uint8)

        # -------------------------------
        # Load the main annotation JSON
        # -------------------------------
        ann_path = getattr(self, "ann_name", None)
        if not ann_path or not os.path.exists(ann_path):
            print(f"[GT_SUP] no annotation JSON for {base_name}")
            return

        with open(ann_path, "r", encoding="utf-8") as f:
            ann_json = json.load(f)

        authoring_atomic = (
            ann_json.get("annotations", {}) or {}
        ).get("atomic_cracks", {}) or {}

        # -----------------------------------------
        # Filter manual atomics ONLY (no snapshots)
        # -----------------------------------------
        def _is_manual(cr):
            src = (cr.get("source") or "").lower()
            return src in ("manual", "manual_poly", "manual_midline")

        atomic = {
            str(cid): cr
            for cid, cr in authoring_atomic.items()
            if _is_manual(cr)
        }

        print(f"[GT_SUP] using {len(atomic)} manual atomics for {base_name}")

        if not atomic:
            print("[GT_SUP] no manual atomics, aborting.")
            return

        # -----------------------------------------
        # GT grouping (midlines + GT mask + endpoints)
        # -----------------------------------------
        combined_groups = gt_groups_from_midlines_and_gtmask(
            atomic=atomic,
            gt_mask=gt_mask,
            H=H,
            W=W,
        )

        print(f"[GT_SUP] GT grouping produced {len(combined_groups)} combined groups.")

        # -----------------------------------------
        # Export manual GT supervision (atomic+combined)
        # -----------------------------------------
        _export_gt_sup(
            base_name=base_name,
            save_root=self.save_folder,
            original_image=self.original_image,
            H=H,
            W=W,
            atomic=atomic,
            combined_groups=combined_groups,
            gt_mask=gt_mask,
        )

        print(f"[GT_SUP] Finished GT supervision export for {base_name}")
     
    def compute_mask_and_width_metrics_for_image(
        self,
        display=False,
        export_supervision=True,
        *,
        cache_key=None,
        include_auto=False,   # enable auto-variant scoring
    ):
        """
        Snapshot-only driver (strict edges). Writes:
        - metrics/<base>/cid{X}/gt_vs_manual_mask_global.png
        - metrics/<base>/cid{X}/gt_normals.png
        - metrics/<base>/combined{C}_{members}/manual/gt_vs_manual_mask_global.png
        - metrics/<base>/combined{C}_{members}/manual/gt_normals.png  (merged normals)
        - metrics/<base>/combined{C}_{members}/auto/gt_vs_auto_mask_global.png
        - metrics/<base>/combined{C}_{members}/auto/auto_normals.png
        - metrics/<base>/mask_metrics.csv
            * atomic, combined, TOTAL
            * atomic_auto, combined_auto, TOTAL_AUTO (when include_auto=True)
        - width diff overlays + per-type CSVs
            * manual: atomic + combined
            * auto:   atomic + combined_auto
        """
        import os, json, numpy as np, pandas as pd, traceback, cv2
        from helpers.metrics import (
            compute_mask_metrics,
            boundary_fscore,
            assd_hd95,
            reconstruct_manual_mask_from_edges,
            mask_iou,
            has_valid_mask,
            safe_write_json,
            metric_atomic_path_for,
            compare_widths_for_cracks,
            write_width_diff_overlay,
            safe_read_json,
            merged_metric_atomic,
        )
        from helpers.combine_debug import _mask_from_crack, auto_groups_from_atomic
        from combiner import build_combined_crack_stateless
        from helpers import metrics as metrics_mod   # for _auto_cache_key
        #from helpers.plot_metrics import save_gt_vs_manual_overlay
        from helpers.supervision import export_gt_supervision_for_image as _export_gt_sup
        #from cracktools.segmentation import generate_mask_from_edges

        print(f"[DEBUG METRICS] ===== START for {getattr(self, 'name', '?')} =====")
        if getattr(self, "current_mask", None) is None:
            print("[DEBUG METRICS] ⚠ no GT mask loaded")
            return {}

        base_name   = self._image_base()
        metrics_dir = self._metrics_dir()
        os.makedirs(metrics_dir, exist_ok=True)

        # supervision root for this image (for GT normals)
        gt_sup_root = os.path.join(self.save_folder, "supervision", base_name)

        ann_path = getattr(self, "ann_name", None)
        if not ann_path or not os.path.exists(ann_path):
            print(f"[DEBUG METRICS] ⚠ no annotation found for {base_name}")
            return {}

        with open(ann_path, "r", encoding="utf-8") as f:
            ann_json = json.load(f)
        authoring_atomic = (ann_json.get("annotations", {}) or {}).get("atomic_cracks", {}) or {}

        H, W = self.original_image.shape[:2]
        gt_full = (self.current_mask > 0).astype(np.uint8)

        # ------------------------------------------------------------------
        # 1) Merge from snapshots – manual view of atomics only
        # ------------------------------------------------------------------
        atomic_all = merged_metric_atomic(authoring_atomic, self.save_folder, base_name)
        print(f"[DEBUG METRICS] merged {len(atomic_all)} atomic cracks after edge snapshots merge")

        def _is_manual(cr):
            src = (cr.get("source") or "").lower()
            return src in ("manual", "manual_poly", "manual_midline")

        atomic = {cid: cr for cid, cr in atomic_all.items() if _is_manual(cr)}
        print(f"[DEBUG METRICS] using {len(atomic)} manual cracks for mask/width metrics")

        # ------------------------------------------------------------------
        # 2) Build AUTO atomic set from per-cid snapshots (auto_best)
        # ------------------------------------------------------------------
        auto_atomic = {}
        if include_auto:
            if cache_key is None:
                cache_key = metrics_mod._auto_cache_key(self)

            print(f"[DEBUG METRICS] authoring_atomic keys: {list(authoring_atomic.keys())}")
            for cid in authoring_atomic.keys():
                scid = str(cid)
                p = metric_atomic_path_for(self.save_folder, base_name, scid)
                snap = safe_read_json(p, {})
                if not snap:
                    continue

                ab = snap.get("auto_best")
                if not isinstance(ab, dict):
                    continue

                mid_auto = np.asarray(ab.get("midline", []), float)
                if mid_auto.ndim != 2 or mid_auto.shape[1] != 2 or len(mid_auto) < 3:
                    continue

                ge_auto = ab.get("geodesic_edges")
                if not isinstance(ge_auto, dict) or not ge_auto.get("edge1") or not ge_auto.get("edge2"):
                    # fall back to snapshot-level geodesics if auto_best didn't persist them
                    ge_auto = snap.get("geodesic_edges", {}) or {}

                # --------------------------------------------------
                # AUTO ATOMIC (INHERIT MANUAL TOPOLOGY)
                # --------------------------------------------------
                auto_cr = {
                    "midline": mid_auto.tolist(),
                    "geodesic_edges": ge_auto,
                    "mask_bbox": snap.get("mask_bbox"),
                    "mask_crop": snap.get("mask_crop"),
                    "timing": snap.get("timing", {}),
                    "source": "auto_best",

                    # CRITICAL: preserve manual topology for grouping
                    "user_points": snap.get("user_points", []),
                    "user_connections": snap.get("user_connections", []),
                }
                auto_atomic[scid] = auto_cr

                auto_atomic[scid] = auto_cr

            print(f"[DEBUG METRICS] built {len(auto_atomic)} auto_best cracks for mask/width metrics")
        else:
            print("[DEBUG METRICS] auto metrics disabled for this call.")

        # ------------------------------------------------------------------
        # 3) Grouping + rebuild (MANUAL + AUTO combined) via combiner
        # ------------------------------------------------------------------
        combine_debug_root = os.path.join(metrics_dir, "combine_debug")

        authoring_combined = auto_groups_from_atomic(
            atomic,
            image_hw=(H, W),
            px_thresh=10.0,
            debug_root=combine_debug_root
        )
        print(f"[COMBINE_DBG] synthesized {len(authoring_combined)} combined groups automatically.")

        # ------------------------------------------------------------------
        # 3.5) CORRECT GT SUPERVISION EXPORT (ATOMIC + GT GROUPED COMBINED)
        # ------------------------------------------------------------------
        if export_supervision:
            try:
                from combiner import gt_groups_from_midlines_and_gtmask

                gt_combined = gt_groups_from_midlines_and_gtmask(
                    atomic=atomic,
                    gt_mask=gt_full,
                    H=H,
                    W=W,
                )

                print(f"[GT_SUP] GT-based combined groups = {len(gt_combined)}")

                _export_gt_sup(
                    base_name=base_name,
                    save_root=self.save_folder,
                    original_image=self.original_image,
                    H=H,
                    W=W,
                    atomic=atomic,
                    combined_groups=gt_combined,
                    gt_mask=gt_full,
                )

                print(f"\n[DEBUG METRICS] GT supervision export completed for {base_name}\n")

            except Exception as e:
                print(f"\n[DEBUG METRICS] GT supervision export failed: {e}\n")
                traceback.print_exc()

        # ------------------------------------------------------------------
        # 4) Rebuild combined cracks for MANUAL + AUTO (shared logic)
        # ------------------------------------------------------------------
        def plot_combined_debug(
            *,
            original_image,
            segs,
            edge1_segs,
            edge2_segs,
            norm1_segs,
            norm2_segs,
            mask_bbox,
            member_ids,
            out_dir,
        ):
            os.makedirs(out_dir, exist_ok=True)
            out_png = os.path.join(out_dir, "edges_midlines_normals_pretty.png")
            from edge_workers import plot_edges_and_normals
            plot_edges_and_normals(
                base_image=original_image,
                midline_segs=segs,
                edge1_segs=edge1_segs,
                edge2_segs=edge2_segs,
                norm1_segs=norm1_segs,
                norm2_segs=norm2_segs,
                bbox=mask_bbox,
                out_png=out_png,
                title=f"Combined Crack (members={', '.join(member_ids)})",
            )

        def _rebuild_combined_map_for_mode(*, mode_label, atomic_src):
            """
            mode_label: 'manual' or 'auto'
            atomic_src: dict of atomic cracks to combine
            """
            out = {}
            for ccid, cmb in (authoring_combined or {}).items():
                members = cmb.get("members", []) or []
                if not members:
                    continue

                semantic_id = cmb.get("semantic_id") or "_".join(map(str, members)) or str(ccid)

                cmb_root = os.path.join(metrics_dir, f"combined_{semantic_id}")
                mode_dir = os.path.join(cmb_root, mode_label)
                os.makedirs(mode_dir, exist_ok=True)

                def _cb(**dbg):
                    try:
                        plot_combined_debug(
                            original_image=self.original_image,
                            segs=dbg.get("segs"),
                            edge1_segs=dbg.get("edge1_segs"),
                            edge2_segs=dbg.get("edge2_segs"),
                            norm1_segs=dbg.get("norm1_segs"),  # ✅ correct key
                            norm2_segs=dbg.get("norm2_segs"),  # ✅ correct key
                            mask_bbox=dbg.get("mask_bbox"),
                            member_ids=members,
                            out_dir=mode_dir,
                        )
                    except Exception as e:
                        print(f"[{mode_label.upper()}_COMBINE_DBG] debug_callback failed: {e}")

                rebuilt = build_combined_crack_stateless(
                    original_image=self.original_image,
                    authoring_atomic=atomic_src,
                    member_ids=[str(m) for m in members],
                    window_half_size=45, mu=0.0, l=5, p=14,
                    color_channel=0, pad=10, prefer_gpu=True,
                    debug_dir=mode_dir,
                    crack_mask_full=self.current_mask,
                    #crack_mask_full=self.full_prediction_mask,
                    debug_callback=_cb,
                )
                rebuilt["members"] = members
                out[str(ccid)] = rebuilt
            return out

        combined_map = _rebuild_combined_map_for_mode(mode_label="manual", atomic_src=atomic)

        auto_combined_map = {}
        if include_auto and auto_atomic:
            auto_combined_map = _rebuild_combined_map_for_mode(mode_label="auto", atomic_src=auto_atomic)

        # ------------------------------------------------------------------
        # 5–8) MASK METRICS + WIDTH METRICS (UNIFIED; minimal duplication)
        # ------------------------------------------------------------------
        mask_rows = []

        def _append_mask_row(
            *,
            crack_type,
            crack_id,
            members,
            base,
            bnd,
            surf,
            supervision,   # <-- NEW, REQUIRED
        ):
            row = {
                "image": base_name,
                "crack_type": crack_type,     # atomic / combined / TOTAL
                "supervision": supervision,   # manual / auto
                "crack_id": str(crack_id) if crack_id is not None else "",
                "members": members or "",
            }
            row.update(base)
            row.update(bnd)
            row.update(surf)
            mask_rows.append(row)

        def _compute_and_record_atomic_metrics(
            *,
            atomic_src,
            combined_src,
            crack_type,
            supervision,
        ):
            """
            Atomic metrics:
            - Metrics are computed ONLY on the bbox crop
            - Returned mask is full-image for TOTAL aggregation
            - Skips atomics that are members of combined cracks (manual + auto)
            """
            agg = np.zeros((H, W), np.uint8)

            # atomics that belong to combined cracks should be excluded
            combined_members_flat = {
                str(m)
                for g in (combined_src or {}).values()
                for m in (g.get("members") or [])
            }

            for cid, crack in (atomic_src or {}).items():
                scid = str(int(cid))

                if scid in combined_members_flat:
                    continue

                try:
                    # --------------------------------------------------
                    # Build FULL-image prediction mask (authoritative)
                    # --------------------------------------------------
                    m_full = _mask_from_crack(crack, H, W)
                    if m_full is None or not np.any(m_full):
                        continue

                    # --------------------------------------------------
                    # Extract bbox + crop (for METRICS ONLY)
                    # --------------------------------------------------
                    bb = crack.get("mask_bbox")
                    if not bb or len(bb) != 4:
                        continue

                    x, y, w, h = map(int, bb)
                    if w <= 0 or h <= 0:
                        continue

                    x0 = max(0, x)
                    y0 = max(0, y)
                    x1 = min(W, x + w)
                    y1 = min(H, y + h)

                    if x1 <= x0 or y1 <= y0:
                        continue

                    gt_crop   = gt_full[y0:y1, x0:x1]
                    pred_crop = m_full[y0:y1, x0:x1]

                    if not np.any(pred_crop):
                        continue

                    # --------------------------------------------------
                    # Metrics computed ONLY on the crop
                    # --------------------------------------------------
                    base = compute_mask_metrics(gt_crop, pred_crop)
                    bnd  = boundary_fscore(gt_crop, pred_crop, tau=2.0)
                    surf = assd_hd95(gt_crop, pred_crop)

                    _append_mask_row(
                        crack_type=crack_type,   # "atomic"
                        crack_id=scid,
                        members="",
                        base=base,
                        bnd=bnd,
                        surf=surf,
                        supervision=supervision, # manual / auto
                    )

                    # --------------------------------------------------
                    # Aggregate FULL-image mask for TOTAL
                    # --------------------------------------------------
                    agg |= (m_full > 0).astype(np.uint8)

                    print(
                        f"[DEBUG MASK] atomic cid={scid} "
                        f"IoU={base['iou']:.4f} bF1={bnd['boundary_f1']:.4f}"
                    )

                except Exception as e:
                    print(f"[atomic fail] cid={scid}: {e}")
                    traceback.print_exc()

            return agg

        def _plot_normals_and_width_overlay_on_crop(
            *,
            out_dir,
            gt_crop,
            pred_crop,
            x0, y0,
            mid_global,
            e1_global,
            e2_global,
            out_normals_name="placeholder_normals.png",
            out_iou_name="gt_vs_pred_mask.png",
            out_width_name="widths_colormap_on_crop.png",
        ):
            """
            Shared pretty plots: normals + width colormap on crop.
            Uses e1/e2 provided (authoritative) and only does visualization.
            """
            try:
                from helpers import plot_metrics
                from edge_workers import plot_widths_colormap_on_crop

                os.makedirs(out_dir, exist_ok=True)

                # iou-ish pretty crop overlay (same style for both modes)
                img_norm = cv2.cvtColor(self.original_image[y0:y0 + gt_crop.shape[0], x0:x0 + gt_crop.shape[1]], cv2.COLOR_BGR2GRAY)

                gt_bin   = (gt_crop > 0).astype(np.uint8)
                pred_bin = (pred_crop > 0).astype(np.uint8)

                intersect = np.logical_and(gt_bin, pred_bin)
                pred_only = np.logical_and(pred_bin, ~gt_bin)
                gt_only   = np.logical_and(gt_bin, ~pred_bin)

                vis_gray  = cv2.cvtColor(img_norm, cv2.COLOR_GRAY2RGB).astype(np.float32) / 255.0
                dark_base = np.clip(vis_gray * 0.35, 0, 1.0)
                overlay   = dark_base.copy()

                overlay[gt_only == 1]   = (.2, 0.2, 1.0)
                overlay[pred_only == 1] = (.2, 1.0, 1.0)
                overlay[intersect == 1] = (0.95, 0.95, 0.95)

                blended  = cv2.addWeighted(overlay, 0.85, dark_base, 0.15, 0)
                blended  = np.clip(blended * 255.0, 0, 255).astype(np.uint8)

                vis_large = cv2.resize(blended, None, fx=3, fy=3, interpolation=cv2.INTER_NEAREST)

                out_iou = os.path.join(out_dir, out_iou_name)
                cv2.imwrite(out_iou, vis_large)
                print(f"[COMBINE_DBG] wrote → {out_iou}")

                # plot normals on pred crop (same frame)
                if mid_global is not None and e1_global is not None and e2_global is not None:
                    mid_plot = np.asarray(mid_global, float).copy()
                    e1 = np.asarray(e1_global, float).copy()
                    e2 = np.asarray(e2_global, float).copy()

                    # shift to crop frame
                    mid_plot[:, 0] -= x0
                    mid_plot[:, 1] -= y0
                    e1[:, 0] -= x0; e1[:, 1] -= y0
                    e2[:, 0] -= x0; e2[:, 1] -= y0

                    out_normals = os.path.join(out_dir, out_normals_name)
                    plot_metrics.plot_gt_normals_on_gtbw(
                        (pred_crop * 255).astype(np.uint8),
                        mid_plot,
                        e1,
                        e2,
                        out_normals,
                    )

                    # width colormap
                    out_width = os.path.join(out_dir, out_width_name)
                    S = 3.0
                    plot_widths_colormap_on_crop(
                        gt_vs_manual_rgb = vis_large,
                        e1               = e1 * S,
                        e2               = e2 * S,
                        midline_xy       = mid_plot * S,
                        track_e1         = None,
                        track_e2         = None,
                        out_png          = out_width,
                    )
                    print(f"[COMBINE_DBG] wrote → {out_width}")

            except Exception as e:
                print(f"[COMBINE_DBG] pretty/width overlay failed: {e}")

        def _compute_and_record_combined_metrics(
            *,
            combined_src,
            atomic_src_for_auto=None,
            crack_type,
            supervision,
        ):
            """
            Combined metrics (MANUAL + AUTO unified).

            Rules:
            - Metrics computed ONLY on bbox crop
            - Returned mask is FULL-image for TOTAL aggregation
            - All legacy plots are restored

            supervision:
            - "manual"
            - "auto"
            """
            agg = np.zeros((H, W), np.uint8)
            is_auto = (supervision == "auto")

            for ccid, cmb in (combined_src or {}).items():
                try:
                    members = cmb.get("members") or []
                    if not members:
                        continue

                    semantic_id = (
                        cmb.get("semantic_id")
                        or "_".join(map(str, members))
                        or str(ccid)
                    )

                    # --------------------------------------------------
                    # Output directories (RESTORED)
                    # --------------------------------------------------
                    cmb_root = os.path.join(metrics_dir, f"combined_{semantic_id}")
                    mode_dir = os.path.join(cmb_root, "auto" if is_auto else "manual")
                    os.makedirs(mode_dir, exist_ok=True)

                    # --------------------------------------------------
                    # Build FULL-image combined mask + bbox crop
                    # --------------------------------------------------
                    if not is_auto:
                        # ---------- MANUAL ----------
                        bb   = cmb.get("mask_bbox")
                        crop = cmb.get("mask_crop")
                        if not bb or crop is None:
                            print(f"[COMBINE_DBG] ⚠️ combined {ccid} missing mask_crop/bbox — skipping.")
                            continue

                        x, y, w, h = map(int, bb)
                        if w <= 0 or h <= 0:
                            continue

                        x0 = max(0, x)
                        y0 = max(0, y)
                        x1 = min(W, x + w)
                        y1 = min(H, y + h)
                        if x1 <= x0 or y1 <= y0:
                            continue

                        pred_crop = (np.asarray(crop, np.uint8) > 0).astype(np.uint8)

                        combined_mask = np.zeros((H, W), np.uint8)
                        combined_mask[y0:y1, x0:x1] = pred_crop[:(y1-y0), :(x1-x0)]

                    else:
                        # ---------- AUTO ----------
                        if atomic_src_for_auto is None:
                            continue

                        combined_mask = np.zeros((H, W), np.uint8)
                        boxes = []

                        for m in members:
                            cr = atomic_src_for_auto.get(str(m))
                            if not cr:
                                continue

                            mm = _mask_from_crack(cr, H, W)
                            if mm is None or not np.any(mm):
                                continue

                            combined_mask |= (mm > 0).astype(np.uint8)

                            ys, xs = np.where(mm)
                            boxes.append([xs.min(), ys.min(), xs.max(), ys.max()])

                        if not np.any(combined_mask):
                            print(f"[COMBINE_DBG] ⚠️ combined {ccid} empty (auto) — skipping.")
                            continue

                        if boxes:
                            x0 = max(min(b[0] for b in boxes) - 5, 0)
                            y0 = max(min(b[1] for b in boxes) - 5, 0)
                            x1 = min(max(b[2] for b in boxes) + 5, W)
                            y1 = min(max(b[3] for b in boxes) + 5, H)
                        else:
                            x0, y0, x1, y1 = 0, 0, W, H

                        pred_crop = combined_mask[y0:y1, x0:x1]

                    # --------------------------------------------------
                    # Crop GT (metrics ONLY here)
                    # --------------------------------------------------
                    gt_crop = gt_full[y0:y1, x0:x1]
                    if not np.any(pred_crop):
                        continue

                    # --------------------------------------------------
                    # 🔁 RESTORED: Global GT vs Pred overlay
                    # --------------------------------------------------
                    save_gt_vs_manual_overlay(
                        H, W,
                        gt_full,
                        combined_mask,
                        os.path.join(
                            mode_dir,
                            "gt_vs_auto_mask_global.png"
                            if is_auto else "gt_vs_manual_mask_global.png",
                        ),
                        bbox=[x0, y0, x1 - x0, y1 - y0],
                        original_image=self.original_image,
                    )

                    # --------------------------------------------------
                    # 🔁 RESTORED: Normals + width overlays
                    # --------------------------------------------------
                    src = auto_combined_map.get(str(ccid), {}) if is_auto else cmb
                    ne  = src.get("normal_edge_points", {}) or {}
                    mid = np.asarray(src.get("midline", []), float)

                    e1 = np.asarray(ne.get("edge1", []), float)
                    e2 = np.asarray(ne.get("edge2", []), float)

                    if e1.size == 0 or e2.size == 0 or mid.size == 0:
                        e1 = e2 = mid = None

                    _plot_normals_and_width_overlay_on_crop(
                        out_dir=mode_dir,
                        gt_crop=gt_crop,
                        pred_crop=pred_crop,
                        x0=x0,
                        y0=y0,
                        mid_global=mid,
                        e1_global=e1,
                        e2_global=e2,
                        out_normals_name="auto_normals.png" if is_auto else "manual_normals.png",
                        out_iou_name="gt_vs_auto_mask.png" if is_auto else "gt_vs_manual_mask.png",
                        out_width_name="widths_colormap_on_crop_auto.png"
                                    if is_auto else "widths_colormap_on_crop.png",
                    )

                    # --------------------------------------------------
                    # Metrics (bbox-level ONLY)
                    # --------------------------------------------------
                    base = compute_mask_metrics(gt_crop, pred_crop)
                    bnd  = boundary_fscore(gt_crop, pred_crop, tau=2.0)
                    surf = assd_hd95(gt_crop, pred_crop)

                    _append_mask_row(
                        crack_type="combined",
                        crack_id=str(ccid),
                        members=semantic_id,
                        base=base,
                        bnd=bnd,
                        surf=surf,
                        supervision=supervision,
                    )

                    # --------------------------------------------------
                    # Aggregate FULL-image mask for TOTAL
                    # --------------------------------------------------
                    agg |= (combined_mask > 0).astype(np.uint8)

                    print(
                        f"[DEBUG MASK] combined id={ccid}({semantic_id}) "
                        f"IoU={base['iou']:.4f} bF1={bnd['boundary_f1']:.4f}"
                    )

                except Exception as e:
                    print(f"[DEBUG METRICS] combined id={ccid} failed: {e}")
                    traceback.print_exc()

            return agg

        # ---- MANUAL masks ----
        agg_manual = _compute_and_record_atomic_metrics(
            atomic_src=atomic,
            combined_src=combined_map,
            crack_type="atomic",
            supervision="manual"
        )
        agg_manual |= _compute_and_record_combined_metrics(
            combined_src=combined_map,
            atomic_src_for_auto=None,
            crack_type="combined",
            supervision="manual"
        )

        # TOTAL (manual)
        if int(agg_manual.sum()) > 0:
            base_total = compute_mask_metrics(gt_full, agg_manual)
            bnd_total  = boundary_fscore(gt_full, agg_manual, tau=2.0)
            surf_total = assd_hd95(gt_full, agg_manual)
            _append_mask_row(
                crack_type="TOTAL",
                crack_id="",
                members="",
                base=base_total,
                bnd=bnd_total,
                surf=surf_total,
                supervision="manual"
            )

        # ---- AUTO masks (optional) ----
        agg_auto = np.zeros((H, W), np.uint8)

        if include_auto and isinstance(auto_atomic, dict) and len(auto_atomic) > 0:
            print("[DEBUG MASK] computing AUTO atomic + combined metrics vs GT ...")

            # NOTE:
            # _compute_and_record_atomic_metrics is responsible for skipping
            # atomics that belong to combined groups. Do NOT change order.
            agg_auto |= _compute_and_record_atomic_metrics(
                atomic_src=auto_atomic,
                combined_src=authoring_combined,   # membership info only
                crack_type="atomic",
                supervision="auto"
            )

            agg_auto |= _compute_and_record_combined_metrics(
                combined_src=auto_combined_map,  # authoritative members list
                atomic_src_for_auto=auto_atomic,
                crack_type="combined",
                supervision="auto"
            )

            print(f"[DEBUG MASK] AUTO aggregate pixels = {int(agg_auto.sum())}")

            # TOTAL_AUTO
            if agg_auto.any():
                base_total_auto = compute_mask_metrics(gt_full, agg_auto)
                bnd_total_auto  = boundary_fscore(gt_full, agg_auto, tau=2.0)
                surf_total_auto = assd_hd95(gt_full, agg_auto)

                _append_mask_row(
                    crack_type="TOTAL",
                    crack_id="",
                    members="",
                    base=base_total_auto,
                    bnd=bnd_total_auto,
                    surf=surf_total_auto,
                    supervision="auto"
                )
            else:
                print("[DEBUG MASK] AUTO aggregate mask empty — skipping TOTAL AUTO.")

        # ------------------------------------------------------------------
        # 7) SAVE MASK METRICS CSV (single file; contains manual + auto)
        # ------------------------------------------------------------------
        out_csv = os.path.join(metrics_dir, "mask_metrics.csv")
        pd.DataFrame(mask_rows).to_csv(out_csv, index=False)
        print(f"[DEBUG MASK] wrote → {out_csv}")

        # ------------------------------------------------------------------
        # 8) WIDTH DIFF CHARTS (manual + optional auto) — unified prep
        # ------------------------------------------------------------------
        def _prep_combined_for_width(combined_src):
            """
            Critical: include mask_bbox so compare_widths_for_cracks can zoom.
            """
            out = {}
            for ccid, cmb in (combined_src or {}).items():
                #print(f"\n------------{cmb.keys()}-----------\n")

                mid_segs = cmb.get("midline_segments", [])
                normals  = cmb.get("normal_edge_points", {}) or {}
                bbox     = cmb.get("mask_bbox")      # ✅ required for zoom
                crop     = cmb.get("mask_crop")      # ✅ REQUIRED for pred mask plotting

                if not mid_segs or not normals:
                    continue

                if bbox is None or not (isinstance(bbox, (list, tuple)) and len(bbox) == 4):
                    print(f"[WIDTH WARN] combined {ccid} missing mask_bbox → will plot global")

                out[str(ccid)] = {
                    "midline_segments": mid_segs,
                    "normal_edge_points": normals,
                    "members": cmb.get("members", []),
                    "mask_bbox": bbox,               # ✅ REQUIRED
                    "mask_crop": crop,               # ✅ ADDED (authoritative pred mask)
                    "timing": cmb.get("timing", {}),
                }

                # pass through dominance + segment metadata verbatim
                out[str(ccid)]["midline_segments_meta"] = cmb.get("midline_segments_meta")
                out[str(ccid)]["dominance_meta"] = cmb.get("dominance_meta")
            return out

        # ------------------------------------------------------------------
        # WIDTH METRICS — TOTAL (atomic + combined merged)
        # ------------------------------------------------------------------

        def _run_width_eval_total(
            *,
            atomic_src=None,
            combined_src=None,
            midline_type,
        ):
            """
            Runs width evaluation for atomic + combined cracks.
            For EACH mode:
            - runs compare_widths_for_cracks
            - exports per-mode width metrics (CSV lives at midline root)
            - generates summary bars + width error plots into
                midline/{atomic|combined}/
            """

            import os

            # ------------------------------------------------------------
            # Inline helper: run + summarize ONE mode
            # ------------------------------------------------------------
            def _run_one_mode(
                *,
                crack_type,          # "atomic" | "combined"
                payload,
            ):
                # ------------------------------------------
                # Run width comparison
                # ------------------------------------------
                ret = compare_widths_for_cracks(
                    payload,
                    gt_full,
                    base_name,
                    metrics_dir,
                    display=display,
                    midline_type=midline_type,
                    crack_type=crack_type,
                    return_normals=False,
                    normals_plot=False,
                    gt_sup_root=gt_sup_root,
                )

                if not ret or not ret[0]:
                    print(f"[WIDTH] no rows returned for {crack_type}")
                    return

                rows = ret[0]
                for r in rows:
                    r["source"] = crack_type

                # ------------------------------------------
                # Canonical CSV location (DO NOT move this)
                # ------------------------------------------
                csv_root = os.path.join(metrics_dir, midline_type)
                diffs_csv = os.path.join(
                    csv_root,
                    f"{base_name}_width_diffs_{crack_type}.csv",
                )

                # ------------------------------------------
                # Presentation output directory
                # ------------------------------------------
                out_dir = os.path.join(
                    metrics_dir,
                    midline_type,
                    crack_type,
                )
                os.makedirs(out_dir, exist_ok=True)

                # ------------------------------------------
                # Export metrics (writes CSVs into csv_root)
                # ------------------------------------------
                export_width_metrics_all(
                    metrics_dir,
                    base_name,
                    rows,
                    midline_type,
                    crack_type=crack_type,
                )

                # ------------------------------------------
                # Summary bars
                # ------------------------------------------
                from helpers.present_plots import plot_width_summary_bars

                plot_width_summary_bars(
                    metrics_dir,
                    base_name,
                    os.path.join(
                        out_dir,
                        f"{base_name}_width_summary_bars.png",
                    ),
                )

                # ------------------------------------------
                # Width error plots (guarded)
                # ------------------------------------------
                if not os.path.exists(diffs_csv):
                    print(f"[WIDTH] missing diffs CSV, skipping plots: {diffs_csv}")
                    return

                from helpers.present_plots import (
                    plot_relative_width_error_kde,
                    plot_width_error_hexbin,
                )

                plot_relative_width_error_kde(
                    diffs_csv,
                    os.path.join(
                        out_dir,
                        f"{base_name}_relative_width_error_kde.png",
                    ),
                )

                plot_width_error_hexbin(
                    diffs_csv,
                    os.path.join(
                        out_dir,
                        f"{base_name}_width_error_hexbin.png",
                    ),
                )

                print(f"[WIDTH] finished summaries for {crack_type}")

            # ------------------------------------------------------------
            # ATOMIC
            # ------------------------------------------------------------
            if atomic_src is not None:
                _run_one_mode(
                    crack_type="atomic",
                    payload={"atomic_cracks": atomic_src},
                )

            # ------------------------------------------------------------
            # COMBINED
            # ------------------------------------------------------------
            if combined_src is not None:
                _run_one_mode(
                    crack_type="combined",
                    payload={"combined_cracks": combined_src},
                )

        # ------------------------------------------------------------------
        # DRIVER
        # ------------------------------------------------------------------
        try:
            print("[DEBUG METRICS] width comparisons (total) ...")

            # MANUAL
            combined_for_width = _prep_combined_for_width(combined_map)
            _run_width_eval_total(
                atomic_src=atomic,
                combined_src=combined_for_width,
                midline_type="manual",
            )

            # AUTO
            if include_auto and auto_atomic:
                combined_auto_for_width = _prep_combined_for_width(auto_combined_map)
                _run_width_eval_total(
                    atomic_src=auto_atomic,
                    combined_src=combined_auto_for_width,
                    midline_type="auto",
                )

        except Exception as e:
            print(f"[DEBUG WIDTH] failed: {e}")
            traceback.print_exc()
            
        # ------------------------------------------------------------------
        # 9) CORE RUNTIME SUMMARY (edge_masks, edge_tracking, combine)
        # ------------------------------------------------------------------
        try:
            timing_rows = []

            def _accum_timing(
                crack_map,
                crack_type,
                *,
                supervision,           # "manual" or "auto"
                prefer_semantic_id=False,
            ):
                for cid, cr in (crack_map or {}).items():
                    if not isinstance(cr, dict):
                        continue

                    # pull timing
                    tdict = cr.get("subtiming")
                    if not isinstance(tdict, dict) or not tdict:
                        tdict = cr.get("timing")
                    if not isinstance(tdict, dict) or not tdict:
                        print(f"[TIMING DBG] skip {crack_type} cid={cid}: no timing")
                        continue

                    # extract algorithm variant safely
                    algo_variant = tdict.get("mode")  # "new"/"old"
                    tdict = dict(tdict)
                    tdict.pop("mode", None)            # 🔥 remove collision

                    # crack id
                    if prefer_semantic_id:
                        crack_id = cr.get("semantic_id") or cr.get("members_str") or str(cid)
                        #print(crack_id, cr.keys())
                    else:
                        crack_id = str(cid)

                    row = {
                        "crack_type": crack_type,        # atomic / combined
                        "supervision": supervision,      # manual / auto
                        "algo_variant": algo_variant,    # new / old / None
                        "crack_id": crack_id,
                    }

                    row.update(tdict)
                    timing_rows.append(row)

                    print(
                        f"[TIMING DBG] add {crack_type} "
                        f"id={crack_id} supervision={supervision} algo={algo_variant}"
                    )

            # -----------------------------
            # MANUAL
            # -----------------------------
            _accum_timing(
                atomic,
                "atomic",
                supervision="manual",
                prefer_semantic_id=False,
            )
            _accum_timing(
                combined_map,
                "combined",
                supervision="manual",
                prefer_semantic_id=True,
            )

            # -----------------------------
            # AUTO
            # -----------------------------
            if include_auto and auto_atomic:
                _accum_timing(
                    auto_atomic,
                    "atomic",
                    supervision="auto",
                    prefer_semantic_id=False,
                )
                _accum_timing(
                    auto_combined_map,
                    "combined",
                    supervision="auto",
                    prefer_semantic_id=True,
                )

            if timing_rows:
                timing_df = pd.DataFrame(timing_rows)

                # enforce schema (defensive)
                for col in ("crack_type", "supervision", "algo_variant", "crack_id"):
                    if col not in timing_df.columns:
                        timing_df[col] = None

                timing_csv = os.path.join(metrics_dir, "timings_core.csv")
                timing_df.to_csv(timing_csv, index=False)

                print("[TIMING DBG] wrote CSV:", timing_csv)
                print(timing_df[["crack_type", "supervision", "algo_variant", "crack_id"]])

                from helpers.plot_metrics import plot_core_timing_bars
                plot_core_timing_bars(metrics_dir)

            else:
                print("[TIMING DBG] no timing rows collected")

        except Exception as e:
            print(f"[DEBUG TIMING] timing summary failed: {e}")
            traceback.print_exc()

        # ------------------------------------------------------------------
        # 10) FINAL SUMMARY / PRESENTATION PLOTS
        # ------------------------------------------------------------------
        try:
            from helpers.present_plots import build_deck_plots_for_image
            print("[DEBUG PLOT] building deck-ready summary plots ...")
            build_deck_plots_for_image(metrics_dir, base_name)
        except Exception as e:
            print(f"[DEBUG PLOT] deck plots failed: {e}")
            traceback.print_exc()

        print(f"[DEBUG METRICS] ===== END for {base_name} =====")
        return {}
       
    # ===============================================================
    # === Smoke test edge worker (cropped + light aware) ============
    # ===============================================================
    def smoke_test_edges_for_manual(self, crack_id, edge_params=None, color_channel=None):
        import os, numpy as np, traceback, cv2

        from edge_workers import edge_param_worker
        from helpers.metrics import (
            metric_atomic_path_for,
            safe_read_json,
            set_tracked_edges_for_crack,
        )

        # -----------------------------------------------------------
        # Load per-crack snapshot
        # -----------------------------------------------------------
        base = self._image_base()
        p = metric_atomic_path_for(self.save_folder, base, crack_id)
        cr = safe_read_json(p, {})

        if not cr:
            print(f"[smoke] ❌ no snapshot for cid={crack_id}")
            return False

        # -----------------------------------------------------------
        # Validate bbox + midline
        # -----------------------------------------------------------
        H, W = self.original_image.shape[:2]

        bb = cr.get("mask_bbox", None)
        if not (isinstance(bb, (list,tuple)) and len(bb)==4):
            print(f"[smoke] ❌ cid{crack_id}: invalid mask_bbox {bb}")
            return False

        x, y, w, h = map(int, bb)
        xmin, ymin, xmax, ymax = x, y, x+w, y+h

        man_xy_g = np.asarray(cr.get("midline", []), float)
        if man_xy_g.ndim != 2 or man_xy_g.shape[1] != 2 or len(man_xy_g) < 2:
            print(f"[smoke] ❌ cid{crack_id}: invalid midline")
            return False

        # -----------------------------------------------------------
        # Setup GUI crop extraction
        # -----------------------------------------------------------
        try:
            self.active_bbox = [xmin, ymin, xmax, ymax]
            self.pts = [man_xy_g[0].copy(), man_xy_g[-1].copy()]
            self.end_points = self.pts
            self.update_image_crop()
            if getattr(self, "skip_current_segment", False):
                return False
        except Exception:
            traceback.print_exc()
            return False

        # -----------------------------------------------------------
        # Channel selection
        # -----------------------------------------------------------
        if color_channel is None:
            color_channel = (
                0 if self.edge_track_color_box.currentText()=="R"
                else 1 if self.edge_track_color_box.currentText()=="B"
                else 2
            )

        gray = self.image_crop[:, :, color_channel].astype(np.float32)
        track_local_yx = np.vstack([man_xy_g[:,1] - y, man_xy_g[:,0] - x])

        if edge_params is None:
            edge_params = {"window_half_size":45, "mu":0.0, "l":5, "p":14, "seg_mode":"new"}

        # -----------------------------------------------------------
        # GT crop for worker
        # -----------------------------------------------------------
        gt_crop = None
        if getattr(self, "current_mask", None) is not None:
            gt_crop = ((self.current_mask[y:y+h, x:x+w]) > 0).astype(np.uint8)

        # -----------------------------------------------------------
        # Global GT + image for worker
        # -----------------------------------------------------------
        if getattr(self, "current_mask", None) is not None:
            gt_full = (self.current_mask > 0).astype(np.uint8)
        else:
            gt_full = np.zeros((H, W), np.uint8)

        # -----------------------------------------------------------
        # Build payload EXACTLY like extract_edge_inputs_for_subcrack()
        # -----------------------------------------------------------
        payload = dict(
            # core image + geometry
            image_crop_gray = gray,
            pts_crop        = self.pts_crop,
            adjusted_track  = track_local_yx,

            # unified midline (always the one we WANT the worker to use)
            midline_global  = man_xy_g,
            midline_type    = "manual",

            bbox            = (x, y, w, h),
            params          = edge_params,
            gt_crop         = gt_crop,

            # global info (for save_gt_vs_manual_overlay)
            image_shape     = (H, W),
            gt_full         = gt_full,
            original_image  = self.original_image,

            # worker-required
            save_folder     = self.save_folder,
            image_base      = base,
            crack_id        = str(crack_id),

            # legacy tag — optional, no longer used for behavior
            source          = "manual",
        )

        # -----------------------------------------------------------
        # Run worker
        # -----------------------------------------------------------
        ew = edge_param_worker(payload)
        if not isinstance(ew, dict):
            print(f"[smoke] ❌ edge worker returned empty for cid{crack_id}")
            return False

        # -----------------------------------------------------------
        # Save results to per-cid snapshot
        # -----------------------------------------------------------
        set_tracked_edges_for_crack(
            self.save_folder,
            base,
            crack_id,
            ew,
            mask_crop=ew.get("mask_crop"),
        )

        cid_path = metric_atomic_path_for(self.save_folder, base, crack_id)
        if os.path.exists(cid_path):
            print(f"[smoke] ✅ updated snapshot → {cid_path}")
        else:
            print(f"[smoke] ❌ expected cid file not found at {cid_path}")

        # -----------------------------------------------------------
        # Optional: Legacy heavy debug (only if DEBUG_SAVE_LIGHT=False)
        # -----------------------------------------------------------
        if not DEBUG_SAVE_LIGHT:
            try:
                # Overlay edges on the original image (legacy)
                ge = cr.get("geodesic_edges", {})
                overlay = self.original_image.copy()
                if overlay.ndim == 2:
                    overlay = cv2.cvtColor(overlay, cv2.COLOR_GRAY2BGR)
                for key, arr in ge.items():
                    arr = np.array(arr, float)
                    if arr.ndim == 2 and len(arr) >= 2:
                        color = (0, 0, 255) if "edge1" in key else (0, 255, 0)
                        cv2.polylines(overlay, [arr.astype(np.int32)], False, color, 1, lineType=cv2.LINE_AA)
                save_dir = os.path.join(self.save_folder, "debug_outputs")
                os.makedirs(save_dir, exist_ok=True)
                out_path = os.path.join(save_dir, f"{base}_cid{crack_id}_edges_overlay.png")
                cv2.imwrite(out_path, overlay)
            except Exception as e:
                print(f"[smoke] overlay(full) failed: {e}")

        print(f"[smoke] ✅ edges ok for cid{crack_id}")
        return True
      
