    # ================= crack_tool.py (metrics snapshot integration) =================

    # ---- 0) tiny shorthands -------------------------------------------------------
    def _image_base(self):
        import os
        return os.path.splitext(os.path.basename(self.name))[0]

    def _metrics_dir(self):
        import os
        return os.path.join(self.save_folder, "metrics", self._image_base())

    # ---- 1) snapshot lifecycle ----------------------------------------------------
    def _ensure_metric_annotations(self):
        if not hasattr(self, "metric_annotations") or self.metric_annotations is None:
            self.metric_annotations = {"atomic_cracks": {}, "combined_cracks": {}, "auto_best_atomic_cracks": {}}

    def _sync_metrics_snapshot_from_authoring(self, refresh_combine=False, persist=False):
        """
        Build per-crack metric snapshot files from self.annotation (read-only inputs only),
        then load self.metric_annotations from those files.

        Does NOT call any GUI builders or mutate self.annotation.
        Combined cracks are never recomputed here — only membership lists are preserved.
        """
        import os
        from helpers.metrics import snapshot_from_authoring, split_snapshot_to_files, load_snapshot_from_files

        base = self._image_base()
        authoring = (self.annotation or {}).get("annotations", {}) or {}

        # Optional refresh of combined membership structure (no geometry)
        if refresh_combine:
            try:
                ann_atomic = dict(authoring.get("atomic_cracks", {}) or {})
                combined_existing = dict(authoring.get("combined_cracks", {}) or {})
                combined_clean = {}

                for k, cmb in combined_existing.items():
                    # Keep only members that still exist in atomics
                    members = [m for m in cmb.get("members", []) if str(m) in ann_atomic]
                    if not members:
                        continue
                    # Copy only membership info; do NOT rebuild geometry here
                    combined_clean[k] = {"members": members}

                authoring = dict(authoring)
                authoring["combined_cracks"] = combined_clean
            except Exception as e:
                print(f"[metrics/snapshot] ⚠ combined membership refresh failed: {e}")

        # --- Snapshot → Disk ---
        snap = snapshot_from_authoring(authoring, cache_key=None)
        split_snapshot_to_files(snap, self.save_folder, base, merge_if_exists=True)

        # (persist flag kept for compatibility; actual persistence is handled by split_snapshot_to_files)
        if refresh_combine and persist:
            pass

        # --- Reload active working snapshot ---
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base)

    def _metric_atomic(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("atomic_cracks", {}) or {}

    def _metric_combined(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("combined_cracks", {}) or {}

    def _metric_auto_best(self):
        self._ensure_metric_annotations()
        return self.metric_annotations.get("auto_best_atomic_cracks", {}) or {}
       
    # ---- 4) Extract inputs for a subcrack (READS SNAPSHOT ONLY) ------------------
    def extract_edge_inputs_for_subcrack(self, crack_id, color_channel=None, prefer_auto_best=False):
        """
        Faithful payload builder for edge_param_worker.

        NEW BEHAVIOR:
        - Reads cid{crack_id}.json
        - If prefer_auto_best=True and auto_best.midline exists and is valid,
          uses that as the midline.
        - Otherwise falls back to the manual midline.

        Returns a payload dict used directly by edge_param_worker.
        """
        import numpy as np
        from helpers.metrics import metric_atomic_path_for, safe_read_json

        cid = str(crack_id)
        base = self._image_base()
        p = metric_atomic_path_for(self.save_folder, base, cid)
        ann = safe_read_json(p, {})

        if not ann:
            print(f"[extract_edge_inputs] cid={cid} ❌ no snapshot at {p}")
            return None

        #print(f'[ANN KEYS] {ann.get("source", "None")}')
        src = (ann.get("source") or "manual").lower()

        # ---------------------------------------------------------
        # Global image + GT (for global overlay)
        # ---------------------------------------------------------
        if getattr(self, "original_image", None) is None:
            print(f"[extract_edge_inputs] cid={cid} ❌ no original_image")
            return None

        H, W = self.original_image.shape[:2]
        if getattr(self, "current_mask", None) is not None:
            gt_full = (self.current_mask > 0).astype(np.uint8)
        else:
            gt_full = np.zeros((H, W), np.uint8)

        # ---------------------------------------------------------
        # 1. BBOX
        # ---------------------------------------------------------
        x, y, w, h = map(int, ann.get("mask_bbox", [0, 0, 0, 0]))
        if w <= 0 or h <= 0:
            print(f"[extract_edge_inputs] cid={cid} ❌ missing/invalid bbox {ann.get('mask_bbox')}")
            return None

        xmin, ymin, xmax, ymax = x, y, x + w, y + h
        self.active_bbox = [xmin, ymin, xmax, ymax]

        # ---------------------------------------------------------
        # 2. Choose midline: manual vs auto_best
        # ---------------------------------------------------------
        man_xy_g = np.asarray(ann.get("midline", []), float)
        auto_xy_g = None
        if "auto_best" in ann and isinstance(ann["auto_best"], dict):
            auto_xy_g = np.asarray(ann["auto_best"].get("midline", []), float)

        midline_type = "manual"
        mid_xy_g = man_xy_g

        def _valid_mid(arr):
            return arr is not None and arr.ndim == 2 and arr.shape[1] == 2 and len(arr) >= 2

        if prefer_auto_best and _valid_mid(auto_xy_g):
            midline_type = "auto_best"
            mid_xy_g = auto_xy_g
        elif not _valid_mid(man_xy_g):
            print(f"[extract_edge_inputs] cid={cid} ❌ no valid manual midline; prefer_auto_best={prefer_auto_best}")
            return None

        print(
            f"[extract_edge_inputs] cid={cid} src={src} "
            f"prefer_auto_best={prefer_auto_best} midline_type={midline_type} "
            f"n_pts={len(mid_xy_g)} bbox=({x},{y},{w},{h})"
        )

        # ---------------------------------------------------------
        # 3. Endpoint setup (same as smoke test)
        # ---------------------------------------------------------
        self.pts = [mid_xy_g[0].copy(), mid_xy_g[-1].copy()]
        self.end_points = self.pts

        # ---------------------------------------------------------
        # 4. Prepare crop + pts_crop
        # ---------------------------------------------------------
        try:
            self.update_image_crop()
            if getattr(self, "skip_current_segment", False):
                print(f"[extract_edge_inputs] cid={cid} segment skipped by update_image_crop")
                return None
        except Exception as e:
            print(f"[extract_edge_inputs] cid={cid} ❌ crop update failed: {e}")
            return None

        # track in local [y,x]
        track_local_yx = np.vstack([
            mid_xy_g[:, 1] - ymin,
            mid_xy_g[:, 0] - xmin,
        ])

        # Flip if needed so start matches pts_crop[0]
        start_xy = track_local_yx[:, 0][::-1]
        d0 = np.linalg.norm(start_xy - self.pts_crop[0])
        d1 = np.linalg.norm(start_xy - self.pts_crop[1])
        if d1 < d0:
            track_local_yx = track_local_yx[:, ::-1]

        # ---------------------------------------------------------
        # 5. Normals (if present)
        # ---------------------------------------------------------
        man_normals_crop = None
        ne = ann.get("normal_edge_points_full") or ann.get("normal_edge_points")
        if isinstance(ne, dict):
            e1 = np.asarray(ne.get("edge1", []), float)
            e2 = np.asarray(ne.get("edge2", []), float)
            e1c = np.column_stack([e1[:, 0] - x, e1[:, 1] - y]) if e1.ndim == 2 else np.empty((0, 2))
            e2c = np.column_stack([e2[:, 0] - x, e2[:, 1] - y]) if e2.ndim == 2 else np.empty((0, 2))
            if len(e1c) and len(e2c):
                man_normals_crop = [[e1c[:, 0], e1c[:, 1]],
                                    [e2c[:, 0], e2c[:, 1]]]

        # ---------------------------------------------------------
        # 6. Gray channel
        # ---------------------------------------------------------
        if color_channel is None:
            color_channel = (
                0 if self.edge_track_color_box.currentText() == "R"
                else 1 if self.edge_track_color_box.currentText() == "B"
                else 2
            )

        gray = self.image_crop[:, :, color_channel].astype(np.float32)

        # clamp endpoints to image crop
        Hc, Wc = gray.shape[:2]
        for p in self.pts_crop:
            p[0] = np.clip(p[0], 0, Wc - 1e-3)
            p[1] = np.clip(p[1], 0, Hc - 1e-3)

        # ---------------------------------------------------------
        # 7. OPTIONAL: GT CROP (same as smoke test)
        # ---------------------------------------------------------
        gt_crop = None
        if getattr(self, "current_mask", None) is not None:
            gt_crop = ((self.current_mask[y:y + h, x:x + w]) > 0).astype(np.uint8)

        # ---------------------------------------------------------
        # 8. FINAL PAYLOAD – FULL MATCH + GLOBAL INFO
        # ---------------------------------------------------------
        return dict(
            image_crop_gray       = gray,
            pts_crop              = self.pts_crop,
            adjusted_track        = track_local_yx,
            midline_global = mid_xy_g,   # this is the midline we actually use
            bbox                  = (x, y, w, h),
            manual_normals_crop   = man_normals_crop,
            gt_crop               = gt_crop,

            # global info for save_gt_vs_manual_overlay
            image_shape           = (H, W),
            gt_full               = gt_full,
            original_image        = self.original_image,

            # bookkeeping / debug
            save_folder           = self.save_folder,
            image_base            = base,
            crack_id              = cid,
            src_tag               = src,
            midline_type          = midline_type,
        )

    def run_edge_tracking_parallel(
        self,
        crack_ids=None,
        cpu_max_workers=None,
        edge_params_fixed=None,
        color_channel=None,
        prefer_auto_best=False,
        plot_only=False,
        per_crack_geom=None,
    ):
        """
        Parallelize edge-mask + edge-tracking and save results into per-crack files.

        - Uses extract_edge_inputs_for_subcrack() as the authoritative payload builder.
          If prefer_auto_best=True, that function will try to use auto_best.midline.
        - Uses _flatten_edge_worker_result() to build timing-aware CSV rows.
        - Writes geodesic edges + masks back into per-cid JSON via set_tracked_edges_for_crack().
        - Reloads snapshot so downstream metrics see updated edges.
        """
        import os, time
        import numpy as np
        import pandas as pd
        from concurrent.futures import ProcessPoolExecutor, as_completed

        from edge_workers import edge_param_worker
        from helpers.metrics import set_tracked_edges_for_crack, load_snapshot_from_files

        # ---------------------------------------------------------------------
        # 0) Sync snapshot from authoring
        # ---------------------------------------------------------------------
        t0 = time.perf_counter()
        self._sync_metrics_snapshot_from_authoring(refresh_combine=False, persist=True)
        atomic = self._metric_atomic()

        if not atomic:
            print("[edge-parallel] ❌ no cracks to process")
            return []

        # ---------------------------------------------------------------------
        # 1) Parameter setup
        # ---------------------------------------------------------------------
        if crack_ids is None:
            crack_ids = list(atomic.keys())

        if color_channel is None:
            color_channel = (
                0 if self.edge_track_color_box.currentText() == "R"
                else 1 if self.edge_track_color_box.currentText() == "B"
                else 2
            )

        if edge_params_fixed is None:
            edge_params_fixed = {"window_half_size": 45, "mu": 0.0, "l": 5, "p": 14}

        if cpu_max_workers is None:
            cpu_max_workers = os.cpu_count()

        base_name   = self._image_base()
        metrics_dir = self._metrics_dir()
        os.makedirs(metrics_dir, exist_ok=True)

        # ---------------------------------------------------------------------
        # 2) Build payloads
        # ---------------------------------------------------------------------
        tasks = []
        for cid in crack_ids:
            payload = self.extract_edge_inputs_for_subcrack(
                cid,
                color_channel=color_channel,
                prefer_auto_best=prefer_auto_best,
            )

            if payload is None:
                continue

            # -------------------------------------------------
            # Plot-only override: inject geom cache
            # -------------------------------------------------
            if plot_only:
                info = (per_crack_geom or {}).get(int(cid), {})
                geom_path = info.get("geom_cache_path", None)

                if not geom_path or not os.path.isfile(geom_path):
                    print(f"[edge-parallel] cid{cid} ❌ no geom cache for plot-only")
                    continue

                payload = dict(payload)   # do not mutate original
                payload["plot_only"] = True
                payload["geom_cache_path"] = geom_path

            # DEBUG: log what midline type we're using
            midline_type = payload.get("midline_type", "manual")
            src_tag = payload.get("src_tag", "?")
            n_pts = len(payload.get("midline_global", []))
            print(
                f"[edge-parallel] cid{cid} midline_type={midline_type} "
                f"src_tag={src_tag} n_pts={n_pts} prefer_auto_best={prefer_auto_best}"
            )

            p = dict(payload)
            p["params"] = dict(edge_params_fixed)
            tasks.append((cid, p))

        if not tasks:
            print("[edge-parallel] nothing to run")
            return []

        print(
            f"[edge-parallel] launching {len(tasks)} edge workers across {cpu_max_workers} CPUs… "
            f"(prefer_auto_best={prefer_auto_best})"
        )
        
        #return

        # ---------------------------------------------------------------------
        # 3) Run workers in parallel
        # ---------------------------------------------------------------------
        rows = []
        with ProcessPoolExecutor(max_workers=cpu_max_workers) as ex:
            futs = {ex.submit(edge_param_worker, p): cid for (cid, p) in tasks}

            for fut in as_completed(futs):
                cid = futs[fut]
                try:
                    ew = fut.result()

                    if isinstance(ew, dict):
                        # Persist results
                        set_tracked_edges_for_crack(
                            self.save_folder,
                            base_name,
                            cid,
                            ew,
                            mask_crop=ew.get("mask_crop"),
                        )

                        # CSV row
                        row = self._flatten_edge_worker_result(
                            crack_id=cid,
                            params=edge_params_fixed,
                            ew=ew,
                        )
                        rows.append(row)

                        print(f"[edge-parallel] cid{cid} ✅")

                    else:
                        print(f"[edge-parallel] cid{cid} empty")

                except Exception as e:
                    print(f"[edge-parallel] cid{cid} ❌ {e}")

        # ---------------------------------------------------------------------
        # 4) Export CSV
        # ---------------------------------------------------------------------
        t_elapsed = time.perf_counter() - t0

        if rows:
            df = pd.DataFrame(rows)
            out_csv = os.path.join(metrics_dir, "edge_parallel_results.csv")
            df.to_csv(out_csv, index=False)
            print(
                f"[edge-parallel] ✅ finished {len(rows)} cracks in {t_elapsed:.2f}s "
                f"({t_elapsed / max(1, len(rows)):.2f}s/crack avg)"
            )
        else:
            print(f"[edge-parallel] ⚠ no successful results (elapsed {t_elapsed:.2f}s)")

        # ---------------------------------------------------------------------
        # 5) Reload snapshot
        # ---------------------------------------------------------------------
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)
        return rows

    # ---------- crack_tool.py (DROP-IN ADDITION inside the class) ----------
    # ---- 6) Auto variants generation (SAVE ONLY TO PER-CRACK FILES) --------------
    # ---------- crack_tool.py (REPLACE the whole function) ----------
    def generate_auto_variants_for_manual_parallel(
        self,
        crack_id,
        g_variants=None,
        cache_key=None,
        force_recompute=True,
        cpu_max_workers=None,
        color_channel=None,
        edge_params_fixed=None,
        *,
        os_ablation=False,
        smoke_test=True,
        os_modes=("old", "new"),
        save_os_cost_png=True,
    ):
        """
        Auto midline variants with OS + RS3 ablation.
        *** Midline-only evaluation version ***

        REQUIRES that per-crack snapshots already exist for cid{crack_id}.
        If not found, this function now auto-syncs once and retries.
        """

        import os, math, numpy as np, pandas as pd, cv2
        import cracktools as ct
        from rs3_split import run_rs3_variants_split, _variant_desc, plot_midlines_overlay_all
        from helpers.metrics import (
            set_auto_variant_for_crack,
            metric_atomic_path_for,
            safe_read_json,
            compute_midline_metrics,
            load_snapshot_from_files,
        )

        # ------------------------------------------------------------
        # 0) Resolve snapshot paths
        # ------------------------------------------------------------
        base_name = self._image_base()
        p_cr = metric_atomic_path_for(self.save_folder, base_name, crack_id)

        # ------------------------------------------------------------
        # 1) Load crack entry; if missing → auto-resync snapshot once
        # ------------------------------------------------------------
        crack = safe_read_json(p_cr, None)

        if not isinstance(crack, dict) or not crack:
            print(f"[AUTO {crack_id}] ❌ snapshot missing → forcing resync…")

            # force-build per-cid JSON files from authoring
            try:
                self._sync_metrics_snapshot_from_authoring(
                    refresh_combine=False,
                    persist=True
                )
            except Exception as e:
                print(f"[AUTO {crack_id}] ❌ resync failed: {e}")
                return None

            # retry loading snapshot after sync
            crack = safe_read_json(p_cr, None)
            if not isinstance(crack, dict) or not crack:
                print(f"[AUTO {crack_id}] ❌ still missing per-crack snapshot after sync")
                return None

        # ------------------------------------------------------------
        # 2) Require manually authored cracks only
        # ------------------------------------------------------------
        src = (crack.get("source") or "").lower()
        if src.startswith("auto") or src == "combined":
            print(f"[AUTO {crack_id}] skip non-manual crack")
            return None

        # ------------------------------------------------------------
        # 3) Validate bbox + midline
        # ------------------------------------------------------------
        try:
            x, y, w, h = map(int, crack.get("mask_bbox", [0, 0, 0, 0]))
        except Exception:
            print(f"[AUTO {crack_id}] ❌ invalid bbox format")
            return None

        if w <= 0 or h <= 0:
            print(f"[AUTO {crack_id}] ❌ no bbox")
            return None

        xmin, ymin, xmax, ymax = x, y, x + w, y + h
        man_xy_g = np.asarray(crack.get("midline", []), float)

        if man_xy_g.ndim != 2 or len(man_xy_g) < 2:
            print(f"[AUTO {crack_id}] ❌ invalid manual midline")
            return None

        # ------------------------------------------------------------
        # 4) Precompute geometry (manual length, bbox area)
        # ------------------------------------------------------------
        seg = man_xy_g[1:] - man_xy_g[:-1]
        man_len_px = float(np.sqrt((seg ** 2).sum(axis=1)).sum())
        bbox_area = float(max(w * h, 1))

        p0 = np.array(man_xy_g[0], float)
        p1 = np.array(man_xy_g[-1], float)

        # ------------------------------------------------------------
        # 5) Ensure cid directory exists
        # ------------------------------------------------------------
        crack_dir = os.path.join(self._metrics_dir(), f"cid{crack_id}", "auto")
        os.makedirs(crack_dir, exist_ok=True)

        # (execution continues unchanged with your existing code)
        
        # -----------------------------------
        # 1) G-variants (midline curvature params)
        # -----------------------------------
        # NOTE:
        # - For real runs: we use the SAME 8 variants for BOTH old/new OS (apples-to-apples).
        # - For smoke_test: we use DIFFERENT single-variant baselines:
        #       new -> (1,25,25)
        #       old -> (1,100,100)
        if g_variants is None:
            # shared 8-variant grid (used when NOT smoke_test)
            g_variants_shared = [
                {"g11": 1.0, "g22": 15.0,  "g33": 15.0},   # local refinement near 25
                {"g11": 1.0, "g22": 25.0,  "g33": 25.0},   # current baseline
                {"g11": 1.0, "g22": 35.0,  "g33": 35.0},   # local refinement near 25
                {"g11": 1.0, "g22": 50.0,  "g33": 50.0},   # moderate curvature
                {"g11": 1.0, "g22": 100.0, "g33": 100.0},  # LEGACY reference (old default)
            ]
        else:
            # user-supplied grid takes precedence
            g_variants_shared = list(g_variants)

        # -----------------------------------
        # 2) OS + cost computation (multi-mode)
        # -----------------------------------
        if color_channel is None:
            color_channel = (
                0 if self.edge_track_color_box.currentText() == "R"
                else 1 if self.edge_track_color_box.currentText() == "B"
                else 2
            )

        self.active_bbox = [xmin, ymin, xmax, ymax]
        self.pts = [p0.copy(), p1.copy()]
        self.end_points = self.pts

        down = (
            self.downsample_factor_box.value()
            if hasattr(self, "downsample_factor_box")
            else getattr(self, "down", 1) or 1
        )

        os_cost_map = {}
        os_cost_timings = {}

        def _run_os_cost_inline(mode_name: str):
            save_dir = crack_dir if save_os_cost_png else None
            cost, timing = self.update_os_cost(
                mode=mode_name, save_dir=save_dir, return_timing=True
            )
            return cost, timing

        if not os_ablation:
            m = getattr(ct.os, "OS_MODE", "new")
            cost, timing = _run_os_cost_inline(m)
            os_cost_map["default"] = cost
            os_cost_timings["default"] = timing
        else:
            for m in os_modes:
                cost, timing = _run_os_cost_inline(m)
                os_cost_map[m] = cost
                os_cost_timings[m] = timing

        # downsampled endpoints
        p0_down_xy = np.asarray(self.pts_crop_down[0], float)
        p1_down_xy = np.asarray(self.pts_crop_down[1], float)

        # -----------------------------------
        # 3) RS3 tracking for each variant
        # -----------------------------------
        variants_out = {}
        metrics_rows = {}
        timing_rows  = {}   # ★ NEW: keep timing separate
        var_local_xy_by_id = {}
        variant_labels_by_id = {}

        global_vid = 0

        for os_mode_name, os_cost in os_cost_map.items():

            # --------------------------------------------------------
            # Choose variants PER OS MODE
            # --------------------------------------------------------
            if smoke_test and g_variants is None:
                # faithful smoke baselines
                if str(os_mode_name).lower() == "old":
                    g_variants_run = [{"g11": 1.0, "g22": 100.0, "g33": 100.0}]
                else:
                    g_variants_run = [{"g11": 1.0, "g22": 25.0, "g33": 25.0}]
            else:
                # normal run: shared balanced set
                g_variants_run = g_variants if g_variants is not None else g_variants_shared

            print(f"[AUTO {crack_id}] === RS3 (mode={os_mode_name}) ===")
            print(
                f"[AUTO {crack_id}] g_variants_run (n={len(g_variants_run)}): "
                f"{[(v['g11'], v['g22'], v['g33']) for v in g_variants_run]}"
            )

            fm_results = run_rs3_variants_split(
                ct=__import__("cracktools"),
                os_cost=os_cost,
                p0_down_xy=p0_down_xy,
                p1_down_xy=p1_down_xy,
                g_variants=g_variants_run,
                down=int(down),
                bbox_xyxy=[xmin, ymin, xmax, ymax],
                cpu_max_workers=(cpu_max_workers or os.cpu_count()),
                mp_start_method="spawn",
            )

            # manual midline in local coordinates
            man_xy_crop = np.column_stack([man_xy_g[:, 0] - x, man_xy_g[:, 1] - y])

            for local_vid, r in enumerate(fm_results):
                vid = global_vid
                global_vid += 1

                if not r.get("ok"):
                    print(f"[AUTO {crack_id}] v{vid} ❌ RS3 failed: {r.get('error')}")
                    continue

                # --------------------------------------------------
                # RS3 track (global XY → (N,2))
                # --------------------------------------------------
                track_xy = np.asarray(r["track_full_xy"], float).T

                # ensure start alignment
                d0 = np.linalg.norm(track_xy[0] - p0)
                d1 = np.linalg.norm(track_xy[0] - p1)
                if d1 < d0:
                    track_xy = track_xy[::-1]
                track_xy = track_xy + (p0 - track_xy[0])

                # local crop coords
                track_crop_xy = np.column_stack([
                    track_xy[:, 0] - x,
                    track_xy[:, 1] - y,
                ])
                var_local_xy_by_id[vid] = track_crop_xy

                # --------------------------------------------------
                # MIDLINE METRICS (FULL DIAGNOSTIC SET)
                # --------------------------------------------------
                m = compute_midline_metrics(track_crop_xy, man_xy_crop)

                # --- selection metrics (AUTHORITATIVE) ---
                ch  = float(m.get("nn_mean_bidirectional", np.inf))
                hd  = float(m.get("hausdorff_max", np.inf))
                cov = float(m.get("coverage_min", 0.0))

                score_mid = (
                    math.log1p(max(ch, 0.0)) +
                    0.5 * math.log1p(max(hd, 0.0)) +
                    (1.0 - float(np.clip(cov, 0.0, 1.0)))
                )

                # IMPORTANT: actual g-params used
                g_used = g_variants_run[local_vid]

                # --------------------------------------------------
                # GEOMETRY METRICS ROW (EXTENDED, CLEAN)
                # --------------------------------------------------
                row = {
                    "image": base_name,
                    "crack_id": crack_id,
                    "variant_global_id": vid,
                    "os_mode": os_mode_name,
                    "g11": float(g_used["g11"]),
                    "g22": float(g_used["g22"]),
                    "g33": float(g_used["g33"]),
                    "length_px": man_len_px,
                    "bbox_area": bbox_area,

                    # --- selection metrics ---
                    "nn_mean_bidirectional": ch,
                    "hausdorff_max": hd,
                    "coverage_min": cov,
                    "score_mid": score_mid,

                    # Diagnostics below are geometry-only summaries.
                    # They are NEVER used for RS3 family selection.
                    "frechet_discrete_ds": m.get("frechet_discrete_ds"),
                    "mean_tan_angle_error_deg": m.get("mean_tan_angle_error_deg"),
                    "relative_length_error": m.get("relative_length_error"),
                    "orth_mean": m.get("orth_mean"),
                    "orth_std": m.get("orth_std"),
                    "signed_bias_z": m.get("signed_bias_z"),
                    "curvature_rms_auto": m.get("curvature_rms_auto"),
                    "curvature_rms_manual": m.get("curvature_rms_manual"),
                    "curvature_rms_ratio": m.get("curvature_rms_ratio"),
                }

                metrics_rows[vid] = row

                # --------------------------------------------------
                # TIMING ROW (UNCHANGED)
                # --------------------------------------------------
                timing_row = {
                    "image": base_name,
                    "crack_id": crack_id,
                    "variant_global_id": vid,
                    "os_mode": os_mode_name,
                    "g11": float(g_used["g11"]),
                    "g22": float(g_used["g22"]),
                    "g33": float(g_used["g33"]),
                }
                timing_row.update(os_cost_timings.get(os_mode_name, {}))
                timing_row.update(r.get("timing", {}))
                timing_rows[vid] = timing_row

                # --------------------------------------------------
                # VARIANT REGISTRATION
                # --------------------------------------------------
                desc = _variant_desc(vid, g_used, edge_params_fixed or {})
                desc["os_mode"] = os_mode_name

                # --------------------------------------------------
                # TOPOLOGY INHERITANCE (FROM MANUAL CRACK)
                # --------------------------------------------------
                variants_out[f"v{vid}"] = {
                    "midline": track_xy.tolist(),
                    "mask_bbox": [x, y, w, h],
                    "params": desc,

                    # inherit manual topology verbatim
                    "user_points": crack.get("user_points", []),
                    "user_connections": crack.get("user_connections", []),
                }

                set_auto_variant_for_crack(
                    self.save_folder,
                    base_name,
                    crack_id,
                    variants_out[f"v{vid}"],
                    params=desc,
                    is_best=False,
                    scores=m,   # full diagnostics preserved
                )

                variant_labels_by_id[vid] = (
                    f"{os_mode_name}: g11={g_used['g11']} "
                    f"g22={g_used['g22']} g33={g_used['g33']}"
                )

                print(f"[AUTO {crack_id}] v{vid} midline_score={score_mid:.4f}")

        # -----------------------------------
        # 4) Best variant selection (LOCAL)
        # -----------------------------------
        best_variant_id = None
        best_flat = None
        metrics_df = None
        timing_df  = None

        if metrics_rows:
            metrics_df = pd.DataFrame(metrics_rows.values())
            metrics_df = metrics_df.sort_values("score_mid", ascending=True)

            metrics_df.to_csv(
                os.path.join(crack_dir, "rs3_variants_ablation.csv"),
                index=False,
            )

            best_variant_id = int(metrics_df.iloc[0]["variant_global_id"])
            print(f"[AUTO {crack_id}] BEST VARIANT (local) = {best_variant_id}")

            best_flat = set_auto_variant_for_crack(
                self.save_folder,
                base_name,
                crack_id,
                variants_out[f"v{best_variant_id}"],
                params=variants_out[f"v{best_variant_id}"]["params"],
                is_best=True,
            )["auto_best"]

        if timing_rows:
            timing_df = pd.DataFrame(timing_rows.values())
            timing_df.to_csv(
                os.path.join(crack_dir, "rs3_variants_timing.csv"),
                index=False,
            )
            
        # -----------------------------------
        # 5) Plot overlays
        # -----------------------------------
        crop_rgb = self.image_crop.copy()
        if crop_rgb.ndim == 2:
            crop_rgb = cv2.cvtColor(crop_rgb, cv2.COLOR_GRAY2BGR)

        man_xy_crop = np.column_stack([man_xy_g[:,0]-x, man_xy_g[:,1]-y])
        print(x,y)

        plot_midlines_overlay_all(
            image_crop_rgb=crop_rgb,
            man_local_xy=man_xy_crop,
            var_local_xy_by_id=var_local_xy_by_id,
            variant_labels_by_id=variant_labels_by_id,
            save_overlay_png=os.path.join(crack_dir, "midlines_overlay_ablation.png"),
            save_legend_png=os.path.join(crack_dir, "midlines_overlay_ablation_legend.png"),
        )

        from helpers.metrics import load_snapshot_from_files
        self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)

        print(f"[AUTO {crack_id}] ✓ completed midline-only ablation")

        # ★ NEW: return metrics_df so callers can do global selection over all subcracks
        return {
            "variants": variants_out,
            "best_variant_id": best_variant_id,
            "best": best_flat,
            "metrics_df": metrics_df,
            "timing_df": timing_df,
        }
        
    def _select_best_rs3_across_subcracks(self, auto_packs_for_image):
        """
        Image-level RS3 family selection across ALL manual subcracks.

        Uses geometry-only metrics (score_mid) for selection.
        All other midline diagnostics are preserved for analysis / appendix,
        but NEVER influence selection.

        Input:
            auto_packs_for_image:
                dict[cid] -> {
                    "variants": {...},
                    "best_variant_id": int,
                    "best": {...},
                    "metrics_df": DataFrame,
                    "timing_df": DataFrame | None,
                }
        """
        import os, json
        import numpy as np
        import pandas as pd
        from helpers.metrics import set_auto_variant_for_crack

        if not auto_packs_for_image:
            print("[AUTO global] no packs to aggregate")
            return

        # ------------------------------------------------------------
        # 1) Collect geometry + timing metrics
        # ------------------------------------------------------------
        geom_frames   = []
        timing_frames = []

        for cid, pack in auto_packs_for_image.items():
            dfm = pack.get("metrics_df")
            if dfm is not None and not dfm.empty:
                d = dfm.copy()
                d["crack_id"] = cid
                geom_frames.append(d)

            dft = pack.get("timing_df")
            if dft is not None and not dft.empty:
                t = dft.copy()
                t["crack_id"] = cid
                timing_frames.append(t)

        if not geom_frames:
            print("[AUTO global] no metrics_df rows to aggregate")
            return

        df_all = pd.concat(geom_frames, ignore_index=True)

        # ------------------------------------------------------------
        # 2) Global weights (length × sqrt(area))
        # ------------------------------------------------------------
        df_all["length_px"]  = df_all["length_px"].fillna(0.01)
        df_all["bbox_area"]  = df_all["bbox_area"].fillna(0.01)

        w_len  = df_all["length_px"].values
        w_area = np.sqrt(df_all["bbox_area"].values)
        w      = np.maximum(w_len * w_area, 1e-3)

        df_all["global_weight"] = w

        # ------------------------------------------------------------
        # 3) Aggregate by RS3 family (SELECTION ONLY)
        # ------------------------------------------------------------
        fam_rows = []
        fam_cols = ["os_mode", "g11", "g22", "g33"]

        for key, g in df_all.groupby(fam_cols):
            ww = g["global_weight"].values
            ss = g["score_mid"].values.astype(float)

            ok = np.isfinite(ss) & np.isfinite(ww) & (ww > 0)
            if not np.any(ok):
                continue

            fam_rows.append({
                "os_mode": key[0],
                "g11": float(key[1]),
                "g22": float(key[2]),
                "g33": float(key[3]),
                "score_mid_wmean": float(np.average(ss[ok], weights=ww[ok])),
                "n_subcracks": int(g["crack_id"].nunique()),
                "n_rows": int(len(g)),
            })

        fam_df = pd.DataFrame(fam_rows)
        if fam_df.empty:
            print("[AUTO global] family table empty")
            return

        fam_df = fam_df.sort_values(
            "score_mid_wmean",
            ascending=True
        ).reset_index(drop=True)

        best = fam_df.iloc[0]
        best_key = (
            best["os_mode"],
            float(best["g11"]),
            float(best["g22"]),
            float(best["g33"]),
        )

        # ------------------------------------------------------------
        # 4) Output directories
        # ------------------------------------------------------------
        base_name   = self._image_base()
        metrics_dir = os.path.join(self._metrics_dir(), "auto")
        os.makedirs(metrics_dir, exist_ok=True)

        plots_dir = os.path.join(metrics_dir, "rs3_plots")
        os.makedirs(plots_dir, exist_ok=True)

        # ------------------------------------------------------------
        # 5) Save CSVs (FULL DIAGNOSTICS PRESERVED)
        # ------------------------------------------------------------
        df_all.to_csv(
            os.path.join(metrics_dir, "rs3_sweep_all_metrics.csv"),
            index=False,
        )

        fam_df.to_csv(
            os.path.join(metrics_dir, "rs3_family_agg.csv"),
            index=False,
        )

        if timing_frames:
            timing_all = pd.concat(timing_frames, ignore_index=True)
            timing_all.to_csv(
                os.path.join(metrics_dir, "rs3_sweep_all_timing.csv"),
                index=False,
            )
        else:
            timing_all = None
        
        # ------------------------------------------------------------
        # 6) Visualization (EXISTING PLOTS ONLY)
        # ------------------------------------------------------------
        try:
            from helpers.present_plots import plot_rs3_sweep_summary

            plot_rs3_sweep_summary(
                df_all,
                plots_dir,
                weight_col="global_weight",
                selected_family=best_key,
            )

            if timing_all is not None and not timing_all.empty:
                from helpers.present_plots import plot_rs3_timing_summary

                plot_rs3_timing_summary(
                    timing_all,
                    plots_dir,
                    selected_family=best_key,
                )

            # Diagnostic-only midline plots (NO SELECTION EFFECT)
            try:
                from helpers.present_plots import plot_rs3_midline_diagnostics
                plot_rs3_midline_diagnostics(
                    df_all=df_all,
                    out_dir=plots_dir,
                    selected_family=best_key,
                )
            except Exception as e:
                print(f"[AUTO global] diagnostic plots skipped: {e}")

        except Exception as e:
            print(f"[AUTO global] ⚠ rs3 summary plot failed: {e}")

        # ------------------------------------------------------------
        # 7) Persist best family JSON
        # ------------------------------------------------------------
        try:
            with open(
                os.path.join(metrics_dir, "rs3_global_best_family.json"),
                "w",
                encoding="utf-8",
            ) as f:
                json.dump({
                    "image": base_name,
                    "os_mode": best_key[0],
                    "g11": best_key[1],
                    "g22": best_key[2],
                    "g33": best_key[3],
                    "score_mid_wmean": float(best["score_mid_wmean"]),
                    "n_subcracks": int(best["n_subcracks"]),
                    "n_rows": int(best["n_rows"]),
                }, f, indent=2)
        except Exception as e:
            print(f"[AUTO global] could not write rs3_global_best_family.json: {e}")

        print(
            f"[AUTO global] best RS3 family: "
            f"mode={best_key[0]}, g11={best_key[1]:.1f}, "
            f"g22={best_key[2]:.1f}, g33={best_key[3]:.1f}, "
            f"score_mid_wmean={best['score_mid_wmean']:.4f}, "
            f"n_subcracks={int(best['n_subcracks'])}"
        )

        # ------------------------------------------------------------
        # 8) Re-mark auto_best for each subcrack (AUTHORITATIVE)
        # ------------------------------------------------------------
        for cid, pack in auto_packs_for_image.items():
            df = pack.get("metrics_df")
            if df is None or df.empty:
                continue

            df_loc = df[
                (df["os_mode"] == best_key[0]) &
                (df["g11"] == best_key[1]) &
                (df["g22"] == best_key[2]) &
                (df["g33"] == best_key[3])
            ]
            if df_loc.empty:
                continue

            vid = int(df_loc.iloc[0]["variant_global_id"])
            vkey = f"v{vid}"
            vdict = pack["variants"].get(vkey)
            if not vdict:
                continue

            params = (vdict.get("params") or {}).copy()
            params.update({
                "os_mode": best_key[0],
                "g11": best_key[1],
                "g22": best_key[2],
                "g33": best_key[3],
            })

            set_auto_variant_for_crack(
                self.save_folder,
                base_name,
                cid,
                vdict,
                params=params,
                is_best=True,
            )

        print("[AUTO global] auto_best updated for all subcracks using global RS3 family.")
    
    # ---- 7) Combined auto masks from snapshot (REPLACE) --------------------------
    def _build_combined_auto_masks_same_indices(self, cache_key=None):
        """
        Build AUTO combined masks from per-crack auto_best + manual combined membership in snapshot.
        """
        import os, cv2, numpy as np, pandas as pd
        from helpers.metrics import _reconstruct_full_mask

        base_name = self._image_base()
        image_dir = self._metrics_dir()
        out_dir   = os.path.join(image_dir, "combined")
        os.makedirs(out_dir, exist_ok=True)

        self._sync_metrics_snapshot_from_authoring(refresh_combine=True, persist=True)
        ann = self.metric_annotations or {}
        atomic   = ann.get("atomic_cracks", {}) or {}
        combined = ann.get("combined_cracks", {}) or {}
        auto_best= ann.get("auto_best_atomic_cracks", {}) or {}

        if not combined: return
        H, W = self.original_image.shape[:2]
        rows = []

        for cmb_id, cmb in combined.items():
            members = cmb.get("members", []) or []
            if not members: continue

            m_manual = _reconstruct_full_mask(cmb, H, W)

            m_auto = np.zeros((H, W), np.uint8)
            for mid in members:
                best = auto_best.get(str(mid))
                if not best: continue
                mm = _reconstruct_full_mask(best, H, W)
                if mm is not None:
                    m_auto |= (mm > 0).astype(np.uint8)

            cv2.imwrite(os.path.join(out_dir, f"combined_{cmb_id}_manual.png"),
                        (m_manual>0).astype(np.uint8)*255)
            cv2.imwrite(os.path.join(out_dir, f"combined_{cmb_id}_auto.png"),
                        (m_auto>0).astype(np.uint8)*255)

            row = {"image": base_name, "combined_id": cmb_id}
            if getattr(self, "current_mask", None) is not None:
                from helpers.metrics import mask_iou
                row["iou_manual_vs_gt"] = mask_iou(m_manual, self.current_mask)
                row["iou_auto_vs_gt"]   = mask_iou(m_auto,   self.current_mask)
            rows.append(row)

        if rows:
            pd.DataFrame(rows).to_csv(os.path.join(out_dir, "combined_metrics.csv"), index=False)
            print(f"[combined] wrote → {os.path.join(out_dir, 'combined_metrics.csv')}")

    # ---- 8) Quick metrics driver (unified; snapshot-only) ----------------------
    def run_metrics_on_current_image_quick(
        self,
        edge_grid=None,
        g_variants=None,
        cpu_max_workers=8,
        do_edge_calibrate=False
    ):
        """
        Fast single-image execution of:
            - snapshot sync from AUTHORING
            - (optional) edge param sweep
            - edge tracking for MANUAL midlines (edge_param_worker + debug)
            - RS3 auto-variants per manual subcrack
            - global RS3 family selection
            - edge tracking for AUTO best (if present)
            - full mask/width metrics + supervision

        Uses the same snapshot structure as batch_run, but without global calibration.
        """
        
        #stopgap measure
        do_edge_calibrate=False

        import os, time, numpy as np, pandas as pd
        from helpers import metrics
        from helpers.save_load_files import load_snapshot_from_files

        if getattr(self, "original_image", None) is None:
            print("[quick] ❌ no image loaded")
            return {}

        base_name = self._image_base()
        print(f"\n[quick] metrics for current image: {base_name}")

        # ------------------------------------------------------------
        # SAFETY CHECK — must have ≥2-pt manual midlines in AUTHORING
        # ------------------------------------------------------------
        ann = (getattr(self, "annotation", {}) or {}).get("annotations", {}) or {}
        atomic_authoring = ann.get("atomic_cracks", {}) or {}

        def _has_valid_manual_midlines(atomic_dict):
            for crack in atomic_dict.values():
                src = (crack.get("source") or "").lower()
                if src.startswith("auto") or src == "combined":
                    continue
                mid = crack.get("midline", [])
                if isinstance(mid, list) and len(mid) >= 2:
                    return True
            return False

        if not atomic_authoring or not _has_valid_manual_midlines(atomic_authoring):
            print(f"[DEBUG QUICK] 🧹 No valid manual midlines — purging snapshot for {base_name}")

            metrics_dir = os.path.join(self.save_folder, "metrics")
            snap_path = os.path.join(metrics_dir, f"{base_name}.json")
            if os.path.exists(snap_path):
                try:
                    os.remove(snap_path)
                    print(f"[DEBUG QUICK] Removed stale snapshot: {snap_path}")
                except Exception as e:
                    print(f"[DEBUG QUICK] ⚠ failed removing {snap_path}: {e}")

            if hasattr(self, "metric_annotations"):
                self.metric_annotations.clear()
                print("[DEBUG QUICK] Cleared in-memory metric_annotations")

            return {}

        # ------------------------------------------------------------
        # SNAPSHOT SYNC (CRITICAL for per-cid files + _metric_atomic)
        # ------------------------------------------------------------
        try:
            self._purge_metrics_for_current_image()
            # Builds metrics/<base>/cid*/cid*.json and sets self.metric_annotations
            self._sync_metrics_snapshot_from_authoring(
                refresh_combine=True,
                persist=True
            )
        except Exception as e:
            print(f"[quick] ⚠ snapshot sync failed: {e}")

        # ------------------------------------------------------------
        # SETUP
        # ------------------------------------------------------------
        image_dir = self._metrics_dir()
        os.makedirs(image_dir, exist_ok=True)
        t_total_start = time.perf_counter()

        # ------------------------------------------------------------
        # (OPTIONAL) EDGE PARAM CALIBRATION
        # ------------------------------------------------------------
        if edge_grid is None:
            edge_grid = {
                "window_half_size": [45],
                "mu": [0],
                "l": [5],
                "p": [14],
                "seg_mode": ["new"],
            }

        # default params (always valid)
        best_edge = {"window_half_size": 45, "mu": 0.0, "l": 5, "p": 14, "seg_mode": "new"}

        t_edge_calib_start = time.perf_counter()

        # ------------------------------------------------------------
        # EDGE PARAM CALIBRATION (NO RECOMPUTE)
        # ------------------------------------------------------------
        if do_edge_calibrate:
            print("[quick] edge calibration sweep...")

            edge_packs = {}

            for cid, cr in self._metric_atomic().items():
                src = (cr.get("source") or "").lower()
                if src.startswith("auto") or src == "combined":
                    continue

                mid = np.asarray(cr.get("midline", []), float)
                if mid.ndim != 2 or len(mid) < 2:
                    continue

                df = self.sweep_edges_with_executor(
                    cid,
                    grid=edge_grid,
                    max_workers=cpu_max_workers,
                )

                if df is not None and not df.empty:
                    d = df.copy()
                    d["crack_id"] = cid
                    edge_packs[cid] = d

            sel = self.select_best_edge_family_across_subcracks(edge_packs)

            # --------------------------------------------------------
            # Normalize selector return shape (IMPORTANT)
            #   - old selector: returns {window_half_size, mu, l, p, seg_mode}
            #   - new selector: returns {"params": {...}, "per_crack_geom": {...}}
            # --------------------------------------------------------
            if sel is None:
                print("[quick] ⚠ edge family selection returned None — fallback to defaults")
                sel = {
                    "params": dict(window_half_size=45, mu=0.0, l=5, p=14, seg_mode="new"),
                    "per_crack_geom": {},
                }

            if isinstance(sel, dict) and "params" in sel:
                # NEW SHAPE
                best_edge_bundle = sel
                best_edge = dict(best_edge_bundle.get("params") or best_edge)
            else:
                # OLD SHAPE
                best_edge_bundle = {"params": dict(sel), "per_crack_geom": {}}
                best_edge = dict(sel)

        else:
            # no calibration → no bundle/caches
            best_edge_bundle = {"params": dict(best_edge), "per_crack_geom": {}}

        # ------------------------------------------------------------
        # APPLY EDGES FROM CACHE (ONLY if calibration produced caches)
        # ------------------------------------------------------------
        used_cache = False
        per_crack_geom = (best_edge_bundle or {}).get("per_crack_geom", {}) or {}

        if do_edge_calibrate and per_crack_geom:
            print("[quick] loading cached edges (no recompute)...")
            used_cache = True

            n_applied = 0
            for cid, info in per_crack_geom.items():
                geom_path = (info or {}).get("geom_cache_path", None)
                if not geom_path:
                    continue

                try:
                    data = np.load(geom_path, allow_pickle=True)

                    # Update the live crack dict directly (safest)
                    cr = self._metric_atomic().get(cid, None)
                    if cr is None:
                        continue

                    # Use .tolist() so JSON snapshot writing stays stable
                    # (np arrays inside dicts will bite you later)
                    if "mask_crop" in data:
                        cr["mask_crop"] = data["mask_crop"].tolist() if hasattr(data["mask_crop"], "tolist") else data["mask_crop"]

                    if "track_e1" in data:
                        cr["edge1"] = data["track_e1"].tolist() if hasattr(data["track_e1"], "tolist") else data["track_e1"]

                    if "track_e2" in data:
                        cr["edge2"] = data["track_e2"].tolist() if hasattr(data["track_e2"], "tolist") else data["track_e2"]

                    # normals
                    n1 = data["normals_e1"] if "normals_e1" in data else None
                    n2 = data["normals_e2"] if "normals_e2" in data else None
                    if n1 is not None or n2 is not None:
                        cr["normals"] = {
                            "edge1": n1.tolist() if hasattr(n1, "tolist") else n1,
                            "edge2": n2.tolist() if hasattr(n2, "tolist") else n2,
                        }

                    # record params used
                    cr["edge_params"] = dict(best_edge)
                    cr["edge_source"] = "cached_calibration"

                    n_applied += 1

                except Exception as e:
                    print(f"[quick] ⚠ cache load failed for cid={cid}: {e}")

            print(f"[quick] cached edges applied to {n_applied} cracks")
        else:
            if do_edge_calibrate:
                print("[quick] no cache map present — will recompute edges in Phase 1")

        t_edge_calib = time.perf_counter() - t_edge_calib_start
        print(f"[quick] ⏱ edge calibration total: {t_edge_calib:.2f}s")

        # ------------------------------------------------------------
        # PHASE 1: EDGE TRACKING FOR MANUAL CRACKS
        #   - If cache was applied: SKIP recompute
        #   - Else: run_edge_tracking_parallel (existing behavior)
        # ------------------------------------------------------------
        if used_cache:
            print("[quick] manual edge tracking skipped (cache already applied)")
            t_manual_edges = 0.0
        else:
            print("[quick] running edge tracking for MANUAL cracks (debug plots)...")
            t_manual_edges_start = time.perf_counter()

            manual_ids = []
            for cid, cr in self._metric_atomic().items():
                src = (cr.get("source") or "").lower()
                if src.startswith("auto") or src == "combined":
                    continue

                mid = np.asarray(cr.get("midline", []), float)
                if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2:
                    continue

                manual_ids.append(cid)

            print(f"[quick] manual cracks to edge-track: {manual_ids}")

            if manual_ids:
                try:
                    _ = self.run_edge_tracking_parallel(
                        crack_ids=manual_ids,
                        cpu_max_workers=cpu_max_workers,
                        edge_params_fixed=best_edge,  # <-- normalized plain params dict
                    )
                except Exception as e:
                    print(f"[quick] ⚠ manual edge tracking failed: {e}")

                # reload snapshot to ensure new edges are visible
                self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)

            t_manual_edges = time.perf_counter() - t_manual_edges_start
            print(f"[quick] manual-edge generation time = {t_manual_edges:.2f}s")
        
        #return
        # ------------------------------------------------------------
        # PHASE 1.5: RS3 AUTO VARIANTS (this image only)
        # ------------------------------------------------------------
        print("[quick] running RS3 auto variants...")
        t_auto_start = time.perf_counter()
        auto_packs = {}

        for cid, cr in self._metric_atomic().items():
            src = (cr.get("source") or "").lower()
            if src.startswith("auto") or src == "combined":
                continue

            mid = np.asarray(cr.get("midline", []), float)
            if mid.ndim != 2 or mid.shape[1] != 2 or len(mid) < 2:
                continue

            pack = self.generate_auto_variants_for_manual_parallel(
                crack_id=cid,
                g_variants=g_variants,
                edge_params_fixed=best_edge,
                cpu_max_workers=cpu_max_workers,
                force_recompute=True,
                os_ablation=False
            )
            if pack:
                auto_packs[cid] = pack

        t_auto = time.perf_counter() - t_auto_start

        # ------------------------------------------------------------
        # PHASE 1.6: SELECT BEST RS3 FAMILY (IMAGE-LEVEL)
        # ------------------------------------------------------------
        print("[quick] selecting best RS3 family for this image...")
        if auto_packs:
            try:
                self._select_best_rs3_across_subcracks(auto_packs)
            except Exception as e:
                print(f"[quick] ⚠ RS3 family selection failed: {e}")
        else:
            print("[quick] ⚠ no auto_packs; skipping RS3 family selection.")
        #return

        # ------------------------------------------------------------
        # PHASE 2: GEODESIC EDGES FOR AUTO BEST MIDLINES
        # ------------------------------------------------------------
        print("[quick] generating geodesic edges for AUTO best midlines...")
        t_auto_edges_start = time.perf_counter()

        auto_ids = []
        for cid, cr in self._metric_atomic().items():
            # Depending on how _select_best_rs3_across_subcracks writes back,
            # this may be either a separate 'auto_best' source or just nested under manual.
            # Here we look for cracks explicitly marked as auto_best.
            src = (cr.get("source") or "").lower()
            if src == "auto_best":
                auto_ids.append(cid)

        print(f"[quick] auto cracks needing edges: {auto_ids}")

        if auto_ids:
            try:
                _ = self.run_edge_tracking_parallel(
                    crack_ids=auto_ids,
                    cpu_max_workers=cpu_max_workers,
                    edge_params_fixed=best_edge,
                    prefer_auto_best=True
                )
            except Exception as e:
                print(f"[quick] ⚠ auto-edgegen failed: {e}")

            # reload snapshot to include AUTO edges
            self.metric_annotations = load_snapshot_from_files(self.save_folder, base_name)

        t_auto_edges = time.perf_counter() - t_auto_edges_start
        print(f"[quick] auto-edge generation time = {t_auto_edges:.2f}s")
        
        #return

        # ------------------------------------------------------------
        # PHASE 3: MASK + WIDTH METRICS + SUPERVISION
        # ------------------------------------------------------------
        t_metrics_start = time.perf_counter()
        try:
            self.compute_mask_and_width_metrics_for_image(
                display=False,
                export_supervision=True,
                include_auto=True
            )
        except Exception as e:
            print(f"[quick] ❌ compute_mask_and_width_metrics_for_image failed: {e}")
            import traceback
            traceback.print_exc()
        t_metrics = time.perf_counter() - t_metrics_start

        # ------------------------------------------------------------
        # LOGGING
        # ------------------------------------------------------------
        total_time = time.perf_counter() - t_total_start
        log_path = os.path.join(image_dir, "runtime_log.csv")

        row = {
            "image": base_name,
            "edge_calibration_s": round(t_edge_calib, 2),
            "edge_generation_manual_s": round(t_manual_edges, 2),
            "auto_variants_s": round(t_auto, 2),
            "auto_edgegen_s": round(t_auto_edges, 2),
            "mask_width_s": round(t_metrics, 2),
            "total_s": round(total_time, 2),
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
        }

        try:
            if os.path.exists(log_path):
                df = pd.read_csv(log_path)
                df = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
            else:
                df = pd.DataFrame([row])
            df.to_csv(log_path, index=False)
        except Exception as e:
            print(f"[quick] ⚠ failed to write runtime_log.csv: {e}")

        print(
            f"[quick] ⏱ total = {total_time:.2f}s "
            f"(edge_calib={t_edge_calib:.2f}s, manual-edgegen={t_manual_edges:.2f}s, "
            f"auto={t_auto:.2f}s, auto-edgegen={t_auto_edges:.2f}s, mask_width={t_metrics:.2f}s)"
        )

        return {"image": base_name, "best_edge": best_edge}
    
    
    
    
